import{_ as o,o as r,c as t,a5 as a}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"其实问题","description":"我又把交易相关代码过了一遍，结合外汇/CFD 经纪商面试里 常问、且你项目里真有实现 的点，整理在下面。前面我们已经写过行情 Worker、WS、K 线、SLTP、NumericInput、万级持仓等，这里 刻意避开重复讲同一套 ，只补「还喜欢问、且项目里能对上代码」的维度。 一。","frontmatter":{"title":"其实问题","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","求职准备"],"description":"我又把交易相关代码过了一遍，结合外汇/CFD 经纪商面试里 常问、且你项目里真有实现 的点，整理在下面。前面我们已经写过行情 Worker、WS、K 线、SLTP、NumericInput、万级持仓等，这里 刻意避开重复讲同一套 ，只补「还喜欢问、且项目里能对上代码」的维度。 一。","sidebarWeight":4,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/简历设计/Max 亮点/其实问题.md"},"headers":[],"relativePath":"posts/前端面试与实战/05-求职准备/Max 亮点/其实问题.md","filePath":"posts/前端面试与实战/05-求职准备/Max 亮点/其实问题.md"}'),i={name:"posts/前端面试与实战/05-求职准备/Max 亮点/其实问题.md"};function d(l,e,s,c,n,u){return r(),t("div",null,[...e[0]||(e[0]=[a('<div><h1 id="其实问题" tabindex="-1">其实问题 <a class="header-anchor" href="#其实问题" aria-label="Permalink to &quot;其实问题&quot;">​</a></h1><blockquote><p>本节目标：理解“其实问题”的核心思路，并能把它用于实际开发或面试表达。 我又把交易相关代码过了一遍，结合外汇/CFD 经纪商面试里<strong>常问、且你项目里真有实现</strong>的点，整理在下面。前面我们已经写过行情 Worker、WS、K 线、SLTP、NumericInput、万级持仓等，这里<strong>刻意避开重复讲同一套</strong>，只补「还喜欢问、且项目里能对上代码」的维度。</p></blockquote><h2 id="一、面试高频-×-你项目里可对上的技术点" tabindex="-1">一、面试高频 × 你项目里可对上的技术点 <a class="header-anchor" href="#一、面试高频-×-你项目里可对上的技术点" aria-label="Permalink to &quot;一、面试高频 × 你项目里可对上的技术点&quot;">​</a></h2><h3 id="_1-bid-ask-与订单方向-最容易被问错的「教科书题」" tabindex="-1">1. Bid/Ask 与订单方向（最容易被问错的「教科书题」） <a class="header-anchor" href="#_1-bid-ask-与订单方向-最容易被问错的「教科书题」" aria-label="Permalink to &quot;1. Bid/Ask 与订单方向（最容易被问错的「教科书题」）&quot;">​</a></h3><ul><li><strong>为什么买用 ask、卖用 bid？持仓的 CURRENT_PRICE 用哪边价？挂单又用哪边？</strong></li><li><strong>代码</strong>：<code>src/views/(public)/trading/_utils/orderPrice.ts</code> 里 <code>applyQuoteToOrder</code>、<code>calculateOrderCurrentPrice</code>（持仓）与 <code>calculatePendingOrderCurrentPrice</code>（挂单）区分开——这是面试官用来筛「有没有真做过终端」的经典题。</li><li><strong>简历一句</strong>：统一封装「持仓 / 挂单」两套 bid-ask 取值规则，避免盈亏与可成交量和后台口径不一致。</li></ul><h3 id="_2-限价单是-limit-还是-stop-由现价与委托价相对位置决定" tabindex="-1">2. 限价单是 Limit 还是 Stop（由现价与委托价相对位置决定） <a class="header-anchor" href="#_2-限价单是-limit-还是-stop-由现价与委托价相对位置决定" aria-label="Permalink to &quot;2. 限价单是 Limit 还是 Stop（由现价与委托价相对位置决定）&quot;">​</a></h3><ul><li><strong>代码</strong>：<code>src/views/(public)/trading/_utils/position.ts</code> 的 <code>getLimitOrderCmd</code>，<code>useOrderBuilder</code> 里组 <code>SocketCmd</code> 前会走这套分支；限价等于现价时直接拦掉并提示（<code>useOrderBuilder</code>）。</li><li><strong>简历一句</strong>：在前端显式推导 Buy/Sell Limit vs Stop，并与当前价校验，减少无效单与后端拒单。</li></ul><h3 id="_3-市场开闭市、节假日、多时区-能不能下单不止看「有没有报价」" tabindex="-1">3. 市场开闭市、节假日、多时区（能不能下单不止看「有没有报价」） <a class="header-anchor" href="#_3-市场开闭市、节假日、多时区-能不能下单不止看「有没有报价」" aria-label="Permalink to &quot;3. 市场开闭市、节假日、多时区（能不能下单不止看「有没有报价」）&quot;">​</a></h3><ul><li><strong>代码</strong>：<code>MarketStatusWrapper.vue</code> 消费 <code>marketCalendarStore.allSymbolMarketStatus</code>，<code>requestSnapshot</code> + Worker 日历（你之前的亮点 4）；另有 <code>useMarketStatus.ts</code> 按 <code>sessions_trade</code> + <code>server_offset_seconds</code> 本地算下一档触发时间。</li><li><strong>简历一句</strong>：交易面板与日历 Worker 联动，仅在市场明确 <code>isOpen</code> 时渲染下单区，闭市展示下次开盘时间（UTC）。</li></ul><h3 id="_4-保证金、最大可开手数、手数步长-pre-trade-规格驱动" tabindex="-1">4. 保证金、最大可开手数、手数步长（Pre-trade / 规格驱动） <a class="header-anchor" href="#_4-保证金、最大可开手数、手数步长-pre-trade-规格驱动" aria-label="Permalink to &quot;4. 保证金、最大可开手数、手数步长（Pre-trade / 规格驱动）&quot;">​</a></h3><ul><li><strong>代码</strong>：<code>TradePanel.vue</code> 手数绑定 <code>min_volume / max_volume / step_volume</code>；<code>AccountInfo.vue</code> 里用 <code>margin_in_user_currency</code> 和 <code>margin_free</code> 用 Decimal 算 <code>maxTradable</code>，并按 <code>min_volume</code> 向下取整到步长。</li><li><strong>简历一句</strong>：手数输入与「按账户币种折算后的每手保证金」联动，约束最大可开手数，避免用户填出后端必拒的单。</li></ul><h3 id="_5-点差、digits、报价有效性-展示与风控习惯" tabindex="-1">5. 点差、Digits、报价有效性（展示与风控习惯） <a class="header-anchor" href="#_5-点差、digits、报价有效性-展示与风控习惯" aria-label="Permalink to &quot;5. 点差、Digits、报价有效性（展示与风控习惯）&quot;">​</a></h3><ul><li><strong>代码</strong>：<code>calculateSpread</code>（pips 整数化）、品种 <code>DIGITS</code> 驱动价格展示；SLTP / NumericInput 等多处与 digits、step 对齐（你已有多条亮点）。</li><li><strong>简历一句</strong>：点差与价格精度与品种规格绑定，保证列表与面板和 MT 口径一致。</li></ul><h3 id="_6-批量平仓-批量改-sltp-部分失败怎么展示" tabindex="-1">6. 批量平仓 / 批量改 SLTP：部分失败怎么展示 <a class="header-anchor" href="#_6-批量平仓-批量改-sltp-部分失败怎么展示" aria-label="Permalink to &quot;6. 批量平仓 / 批量改 SLTP：部分失败怎么展示&quot;">​</a></h3><ul><li><strong>代码</strong>：<code>OrderTabs.vue</code> 里 <code>Promise.allSettled</code> + <code>processBatchResults</code>（<code>src/utils/batchOperationHelper.ts</code>），失败时用 VNode 多行展示每张 ticket 的错误。</li><li><strong>简历一句</strong>：批量指令前端聚合结果，支持部分失败时的结构化错误展示，而不是一句笼统失败。</li></ul><h3 id="_7-部分平仓与折叠-对冲行-业务规则-并发防重" tabindex="-1">7. 部分平仓与折叠/对冲行（业务规则 + 并发防重） <a class="header-anchor" href="#_7-部分平仓与折叠-对冲行-业务规则-并发防重" aria-label="Permalink to &quot;7. 部分平仓与折叠/对冲行（业务规则 + 并发防重）&quot;">​</a></h3><ul><li><strong>代码</strong>：<code>handlePartialClose</code> 对折叠行按子单 <code>Math.min(请求手数, 子单手数)</code> 拆 <code>lots</code> 数组；<code>closeOpenOrder</code> 用 <code>closingOpenTickets</code> / <code>operationId</code> 防重复点。</li><li><strong>简历一句</strong>：折叠持仓下一次平仓请求映射为多 ticket 按比例/上限拆手数，并做 ticket 级防重复提交。</li></ul><h3 id="_8-订单提交路径-幂等感、防抖、通知合并" tabindex="-1">8. 订单提交路径：幂等感、防抖、通知合并 <a class="header-anchor" href="#_8-订单提交路径-幂等感、防抖、通知合并" aria-label="Permalink to &quot;8. 订单提交路径：幂等感、防抖、通知合并&quot;">​</a></h3><ul><li><strong>代码</strong>：<code>useOrderSubmit</code> 里 500ms 最小间隔 + <code>submitting</code>；通知用 <code>payload.seq</code> 作 key 替换同一条「进行中→成功/失败」。</li><li><strong>简历一句</strong>：Socket 下单层做提交节流与通知单例，降低弱网重复点击与通知洪水。</li></ul><h3 id="_9-「多空力道」类情绪-占比条-外网延迟观测" tabindex="-1">9. 「多空力道」类情绪/占比条 + 外网延迟观测 <a class="header-anchor" href="#_9-「多空力道」类情绪-占比条-外网延迟观测" aria-label="Permalink to &quot;9. 「多空力道」类情绪/占比条 + 外网延迟观测&quot;">​</a></h3><ul><li><strong>代码</strong>：<code>TradeForceBar.tsx</code> 定时拉 <code>get_ratio</code>，<code>useTradingNetworkStatus</code> 用往返时间更新外部延迟（给交易体验一个可观测指标）。</li><li><strong>简历一句</strong>：下单面板旁路展示后端聚合的多空占比，并把 HTTP 采样延迟纳入网络状态，辅助排查卡顿。</li></ul><h3 id="_10-账户动态字段与风控心智-和持仓-worker-形成闭环" tabindex="-1">10. 账户动态字段与风控心智（和持仓 Worker 形成闭环） <a class="header-anchor" href="#_10-账户动态字段与风控心智-和持仓-worker-形成闭环" aria-label="Permalink to &quot;10. 账户动态字段与风控心智（和持仓 Worker 形成闭环）&quot;">​</a></h3><ul><li><strong>代码</strong>：<code>useOpenPosition</code> watch <code>totalFloatingPL</code> 推 <code>equity / margin_fee / level_now</code>（你已展开过万级持仓）；类型里还有 <code>MarginLevel</code>、<code>server_offset_seconds</code>、<code>leverage</code> 等字段可与面试延伸。</li></ul><hr><h2 id="二、这些要不要单独写进简历" tabindex="-1">二、这些要不要单独写进简历 <a class="header-anchor" href="#二、这些要不要单独写进简历" aria-label="Permalink to &quot;二、这些要不要单独写进简历&quot;">​</a></h2><ul><li><strong>不必每一条都占一条「Top 亮点」</strong>，否则会和 SLTP、NumericInput、万级持仓、WS、K 线抢篇幅。</li><li><strong>推荐写法</strong>：在「交易终端」项目描述里加 <strong>1 段「订单与报价语义」子 bullet</strong>，把 <strong>(1)(2)(4)</strong> 合成一句；再加 <strong>1 段「批量与部分平仓」</strong> 把 <strong>(6)(7)(8)</strong> 合成一句；<strong>开闭市 (3)</strong> 若简历篇幅够可并入「多时区日历 Worker」那条，写「消费端：交易面板 gating」。</li></ul><hr><h2 id="三、示范简历短句-可直接粘贴改编" tabindex="-1">三、示范简历短句（可直接粘贴改编） <a class="header-anchor" href="#三、示范简历短句-可直接粘贴改编" aria-label="Permalink to &quot;三、示范简历短句（可直接粘贴改编）&quot;">​</a></h2><ol><li><strong>Bid/Ask 与订单类型</strong>：封装持仓/挂单两套报价取用规则，并基于现价与限价自动区分 Limit/Stop，限价等于现价时前置拦截，保证与 MT 下单语义一致。</li><li><strong>规格驱动 + 保证金</strong>：手数输入严格绑定 <code>min/max/step volume</code>，并结合账户币种保证金折算计算理论最大可开手数（Decimal 对齐步长）。</li><li><strong>批量与部分平仓</strong>：批量 <code>sendCmd</code> 使用 <code>allSettled</code> + 可渲染的多行错误；折叠持仓部分平仓按子单手数拆单；ticket 级防重复提交。</li><li><strong>开闭市</strong>：交易面板仅在日历 Worker 判定 <code>isOpen</code> 时渲染下单区，闭市展示下次开盘，避免无效下单请求。</li></ol><hr><h2 id="四、面试官可能追问的「深入题」-你可提前准备" tabindex="-1">四、面试官可能追问的「深入题」（你可提前准备） <a class="header-anchor" href="#四、面试官可能追问的「深入题」-你可提前准备" aria-label="Permalink to &quot;四、面试官可能追问的「深入题」（你可提前准备）&quot;">​</a></h2><ul><li>持仓盈亏若完全信服务端 PUSH，为什么还要本地因子近似？（你项目里是 <code>__profitFactor</code> + 报价批处理那条线。）</li><li>Limit vs Stop 在 <strong>Buy</strong> 侧为什么是「委托价低于现价 → Limit」？画条数轴一句话说清。</li><li>若 <code>margin_in_user_currency</code> 与 <code>margin_free</code> 币种不一致怎么办？（看你们是否保证已折算到账户币。）</li><li>批量操作「部分成功」产品上要 retry 还是人工逐条处理？你们当前是展示逐 ticket 错误。</li></ul><p>若你希望，我可以把上述内容 <strong>直接合并进你之前那份「Top 8 + 技术亮点清单」</strong>，标成「交易语义与风控展示」一节，避免和 Worker/WS 条目重复表述。</p></div>',1)])])}const _=o(i,[["render",d]]);export{h as __pageData,_ as default};
